#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Temperature::new(v, TemperatureUnit::Kelvin),
        Temperature::from_kelvins(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::Kelvin),
        Temperature::from_base(v).as_kelvins()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeCelsius),
        Temperature::from_degrees_celsius(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeCelsius),
        Temperature::from_base(v).as_degrees_celsius()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::MillidegreeCelsius),
        Temperature::from_millidegrees_celsius(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::MillidegreeCelsius),
        Temperature::from_base(v).as_millidegrees_celsius()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeDelisle),
        Temperature::from_degrees_delisle(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeDelisle),
        Temperature::from_base(v).as_degrees_delisle()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeFahrenheit),
        Temperature::from_degrees_fahrenheit(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeFahrenheit),
        Temperature::from_base(v).as_degrees_fahrenheit()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeNewton),
        Temperature::from_degrees_newton(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeNewton),
        Temperature::from_base(v).as_degrees_newton()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeRankine),
        Temperature::from_degrees_rankine(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeRankine),
        Temperature::from_base(v).as_degrees_rankine()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeReaumur),
        Temperature::from_degrees_reaumur(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeReaumur),
        Temperature::from_base(v).as_degrees_reaumur()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::DegreeRoemer),
        Temperature::from_degrees_roemer(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::DegreeRoemer),
        Temperature::from_base(v).as_degrees_roemer()
    );
    assert_eq!(
        Temperature::new(v, TemperatureUnit::SolarTemperature),
        Temperature::from_solar_temperatures(v)
    );
    assert_eq!(
        Temperature::from_base(v).convert_to(TemperatureUnit::SolarTemperature),
        Temperature::from_base(v).as_solar_temperatures()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("K".parse::<TemperatureUnit>(), Ok(TemperatureUnit::Kelvin));
    assert_eq!(
        format!("2.5 {}", "K").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::Kelvin))
    );
    assert_eq!(
        "°C".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "°C").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeCelsius))
    );
    assert_eq!(
        "m°C".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::MillidegreeCelsius)
    );
    assert_eq!(
        format!("2.5 {}", "m°C").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::MillidegreeCelsius))
    );
    assert_eq!(
        "°De".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeDelisle)
    );
    assert_eq!(
        format!("2.5 {}", "°De").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeDelisle))
    );
    assert_eq!(
        "°F".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeFahrenheit)
    );
    assert_eq!(
        format!("2.5 {}", "°F").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeFahrenheit))
    );
    assert_eq!(
        "°N".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeNewton)
    );
    assert_eq!(
        format!("2.5 {}", "°N").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeNewton))
    );
    assert_eq!(
        "°R".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeRankine)
    );
    assert_eq!(
        format!("2.5 {}", "°R").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeRankine))
    );
    assert_eq!(
        "°Ré".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeReaumur)
    );
    assert_eq!(
        format!("2.5 {}", "°Ré").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeReaumur))
    );
    assert_eq!(
        "°Rø".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::DegreeRoemer)
    );
    assert_eq!(
        format!("2.5 {}", "°Rø").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::DegreeRoemer))
    );
    assert_eq!(
        "T⊙".parse::<TemperatureUnit>(),
        Ok(TemperatureUnit::SolarTemperature)
    );
    assert_eq!(
        format!("2.5 {}", "T⊙").parse::<Temperature>(),
        Ok(Temperature::new(2.5, TemperatureUnit::SolarTemperature))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Temperature>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Temperature::from_base(6.0);
    let b = Temperature::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Temperature::<i64>::from_base(7);
    let b = Temperature::<i64>::from_base(2);
    assert_eq!(a + b, Temperature::from_base(9));
    assert_eq!(a % b, Temperature::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<Temperature<i64>>(),
        Temperature::from_base(9)
    );
}
